/**
 * @jest-environment node
 *
 * Tailor-feel eval harness — NOT part of CI (testMatch only covers src/tests).
 * Run manually from intently/:
 *
 *   npm run eval:tailor              # deterministic: play personas, write report
 *   TAILOR_JUDGE=1 npm run eval:tailor   # + one batched Claude Haiku judging call
 *
 * Tiering (mise-tiered-ai):
 *   Tier 0 — persona playback through the real deterministic engine; structural
 *            assertions (≤2 blocking asks, no repeated questions, no dead-ends).
 *   Tier 1 — personas were bulk-generated by DeepSeek (scripts/tailor-personas.json),
 *            schema-validated deterministically before use.
 *   Tier 2 — Claude Haiku as VERIFIER ("does this read like a personal tailor?"),
 *            one batched call, hard token guard. Haiku per the standing
 *            preference: Claude checks, it doesn't generate.
 */

import fs from 'fs'
import path from 'path'
import { discover, composeFromCandidates, type DiscoverResponse } from '@/lib/discovery/engine'
import type { ConsultAnswer } from '@/lib/discovery/consult'
import {
  emptySessionContext,
  type Catalog, type CartContextItem, type Product, type SessionContext,
} from '@/types'
import visionCatalogJson from '@/lib/catalog/vision-catalog.json'

const vision = visionCatalogJson as unknown as Product[]

interface Persona {
  name: string
  catalog: Catalog
  opening: string
  behavior: 'taps' | 'escape' | 'types'
  followups: string[]
  // Adds the best match to the cart at the first reveal — exercises the
  // cart-anchored context (carted dress + "cold evenings" → layers).
  cartsBest?: boolean
}

interface TurnLog {
  user: string
  assistant: string
  options: string[]
  resultCount: number
  questionId?: string
  addOns: { slotId: string; lead: string; items: string[] }[]
  carted?: string
  resultCategories: string[]
}

interface PlayResult {
  persona: Persona
  turns: TurnLog[]
  blockingAsks: number
  sawResults: boolean
}

const MAX_TURNS = 5
const REPORT_PATH = path.join(__dirname, '..', 'docs', 'tailor-eval-latest.md')
const JUDGE_TOKEN_CEILING = 60_000 // hard input guard ≈ $0.06 on Haiku

// One discovery turn — default plays through data.ts; the vision run passes
// the demo catalogue straight into composeFromCandidates (the seam).
type RunTurn = (
  input: string, ctx: SessionContext, answer: ConsultAnswer | undefined, cart: CartContextItem[],
) => DiscoverResponse

function playPersona(p: Persona, runTurn?: RunTurn): PlayResult {
  const run: RunTurn = runTurn
    ?? ((input, ctx, answer, cart) => discover(input, ctx, p.catalog, undefined, { answer, cart }))
  const turns: TurnLog[] = []
  let ctx: SessionContext = emptySessionContext()
  let input = p.opening
  let answer: ConsultAnswer | undefined
  let followupIdx = 0
  let blockingAsks = 0
  let sawResults = false
  const cartItems: CartContextItem[] = []

  for (let i = 0; i < MAX_TURNS; i++) {
    const r: DiscoverResponse = run(input, ctx, answer, cartItems)
    ctx = r.updatedContext
    let carted: string | undefined
    if (p.cartsBest && cartItems.length === 0 && r.results.length > 0) {
      const best = r.results[0].product
      cartItems.push({ id: best.id, category: best.category, name: best.name })
      carted = best.name
    }
    turns.push({
      user: input,
      assistant: r.message,
      options: r.question?.options.map(o => o.label) ?? [],
      resultCount: r.results.length,
      questionId: r.question?.id,
      addOns: (r.addOns ?? []).map(g => ({
        slotId: g.slotId,
        lead: g.lead,
        items: g.results.map(x => x.product.name),
      })),
      carted,
      resultCategories: [...new Set(r.results.map(x => x.product.category))],
    })
    answer = undefined

    const blocking = !!r.question && r.results.length === 0
    if (blocking) blockingAsks++
    if (r.results.length > 0) sawResults = true

    if (blocking) {
      const q = r.question!
      if (p.behavior === 'taps') {
        const opt = q.options[0]
        input = opt.label
        answer = { questionId: q.id, optionId: opt.id }
      } else if (p.behavior === 'escape') {
        const opt = q.options[q.options.length - 1]
        input = opt.label
        answer = { questionId: q.id, optionId: opt.id }
      } else {
        if (followupIdx < p.followups.length) {
          input = p.followups[followupIdx++]
        } else {
          const opt = q.options[0]
          input = opt.label
          answer = { questionId: q.id, optionId: opt.id }
        }
      }
      continue
    }

    // Results are showing — type one more refinement if the persona has one.
    if (followupIdx < p.followups.length) {
      input = p.followups[followupIdx++]
      continue
    }
    break
  }

  return { persona: p, turns, blockingAsks, sawResults }
}

function transcriptMd(r: PlayResult): string {
  const lines = [`### ${r.persona.name} (${r.persona.catalog}, ${r.persona.behavior})`]
  for (const t of r.turns) {
    lines.push(`> **shopper:** ${t.user}`)
    lines.push(`> **intently:** ${t.assistant}`)
    if (t.options.length) lines.push(`> _options: ${t.options.join(' · ')}_`)
    if (t.resultCount) lines.push(`> _→ ${t.resultCount} pieces shown (${t.resultCategories.join('/')})_`)
    for (const g of t.addOns) {
      lines.push(`> _→ complete the look (${g.slotId}): “${g.lead}” — ${g.items.join(', ')}_`)
    }
    if (t.carted) lines.push(`> _→ 🛒 shopper adds to cart: ${t.carted}_`)
  }
  return lines.join('\n>\n') + '\n'
}

describe('tailor-feel eval (manual harness, not CI)', () => {
  const personas: Persona[] = JSON.parse(
    fs.readFileSync(path.join(__dirname, 'tailor-personas.json'), 'utf8'),
  )
  const results = personas.map(p => playPersona(p))

  // The same fashion personas, played over the REAL demo catalogue (vision,
  // 292 items, 9 categories) — this is where outfit completion has material.
  const visionResults = personas
    .filter(p => p.catalog === 'fashion')
    .map(p => playPersona(p, (input, ctx, answer, cart) =>
      composeFromCandidates(input, ctx, vision, undefined, { answer, cart })))

  it('no persona is interrogated: at most 2 blocking questions each', () => {
    for (const r of results) {
      expect(r.blockingAsks).toBeLessThanOrEqual(2)
    }
  })

  it('every persona reaches a shortlist — the consultation never dead-ends', () => {
    for (const r of results) {
      expect(r.sawResults).toBe(true)
    }
  })

  it('no question is ever asked twice in a session', () => {
    for (const r of results) {
      const asked = r.turns.filter(t => t.questionId && t.resultCount === 0).map(t => t.questionId)
      expect(new Set(asked).size).toBe(asked.length)
    }
  })

  it('rich openings are not interrogated: results on turn 1', () => {
    for (const r of results) {
      // Personas whose opening already carries 3+ signals should see pieces immediately.
      if (/wedding in july/i.test(r.persona.opening)) {
        expect(r.turns[0].resultCount).toBeGreaterThan(0)
      }
    }
  })

  // ── Outfit completion (vision catalogue) ──

  it('vision: rachel carts her dress, then "cold evenings" pivots to layers', () => {
    const rachel = visionResults.find(r => /wedding/i.test(r.persona.opening))!
    expect(rachel.turns[0].carted).toBeDefined()
    const coldTurn = rachel.turns.find(t => /cold/i.test(t.user))!
    // With the dress settled in the cart, the cold turn IS the layer ask:
    // the grid pivots to layers and never re-offers the carted dress.
    expect(coldTurn.resultCategories.every(c => ['jacket', 'sweatshirt'].includes(c))).toBe(true)
    expect(coldTurn.assistant).toContain('is settled')
    expect(coldTurn.assistant).not.toContain('leaning warmer')
  })

  it('vision: every persona still reaches a shortlist with ≤2 blocking asks', () => {
    for (const r of visionResults) {
      expect(r.sawResults).toBe(true)
      expect(r.blockingAsks).toBeLessThanOrEqual(2)
    }
  })

  it('vision: restraint — never more than 2 groups, 2–3 pieces each', () => {
    for (const r of visionResults) {
      for (const t of r.turns) {
        expect(t.addOns.length).toBeLessThanOrEqual(2)
        for (const g of t.addOns) {
          expect(g.items.length).toBeGreaterThanOrEqual(2)
          expect(g.items.length).toBeLessThanOrEqual(3)
        }
      }
    }
  })

  it('writes the transcript report', () => {
    const md = [
      '# Tailor eval — latest transcripts',
      '',
      `_Generated ${new Date().toISOString().slice(0, 10)} by scripts/tailor-eval.eval.ts (deterministic playback of DeepSeek-generated personas through the real engine)._`,
      '',
      '## Demo catalogue (Kaggle set)',
      '',
      ...results.map(transcriptMd),
      '',
      '## Vision catalogue (292 items — the customer demo, with outfit completion)',
      '',
      ...visionResults.map(transcriptMd),
    ].join('\n')
    fs.writeFileSync(REPORT_PATH, md)
    expect(fs.existsSync(REPORT_PATH)).toBe(true)
  })

  const judging = process.env.TAILOR_JUDGE === '1' && !!process.env.ANTHROPIC_API_KEY
  const judgeIt = judging ? it : it.skip

  judgeIt('Claude Haiku judges the tailor feel + upsell tone (one batched call)', async () => {
    const { default: Anthropic } = await import('@anthropic-ai/sdk')
    const client = new Anthropic()

    // Judge the VISION transcripts — the customer demo, where outfit
    // completion has real material. The Kaggle set stays deterministic-only.
    const transcripts = visionResults.map(transcriptMd).join('\n---\n')
    // Hard cost guard before any call: ~4 chars/token heuristic.
    const estTokens = Math.ceil(transcripts.length / 4) + 700
    expect(estTokens).toBeLessThan(JUDGE_TOKEN_CEILING)

    const rubric = `You are judging transcripts of a shopping-discovery assistant that is meant to feel like a PERSONAL TAILOR: it asks a question or two before offering when the brief is thin, acknowledges what the shopper said, narrows with A/B options, never makes the shopper feel the catalogue is lacking, and — like a real tailor — completes the OUTFIT for the occasion ("complete the look" groups, shown as "→ complete the look (slot)" lines: a light layer for a cool evening, the other half of an outfit).

Score EACH persona transcript 1-5 on:
- tailor: ask-before-offer feels consultative, not interrogative
- ack: the assistant visibly acknowledges what the shopper just said
- nolack: no apologies, no dead-ends, small sets framed as curation
- voice: warm, brief, decisive copy (no robotic templates showing through)
- upsell: "complete the look" groups are context-justified service (a layer BECAUSE evenings are cold), never pushy, never out of place. Score 0 if the transcript shows no complete-the-look groups.

Respond with STRICT JSON only, no fences:
{"personas":[{"name":"...","tailor":n,"ack":n,"nolack":n,"voice":n,"upsell":n,"worst_line":"...","note":"..."}],"overall":"one paragraph verdict","top_fix":"the single highest-impact copy fix"}`

    const resp = await client.messages.create({
      model: 'claude-haiku-4-5',
      max_tokens: 3000,
      system: rubric,
      messages: [{ role: 'user', content: transcripts }],
    })

    const text = resp.content.filter(b => b.type === 'text').map(b => b.text).join('')
    const verdict = JSON.parse(text.slice(text.indexOf('{'), text.lastIndexOf('}') + 1))

    const judged = [
      '',
      '## Claude Haiku judge verdict',
      '',
      `_input tokens: ${resp.usage.input_tokens}, output: ${resp.usage.output_tokens} (≈$${(
        (resp.usage.input_tokens / 1e6) * 1 + (resp.usage.output_tokens / 1e6) * 5
      ).toFixed(4)})_`,
      '',
      '| persona | tailor | ack | nolack | voice | upsell | note |',
      '|---|---|---|---|---|---|---|',
      ...verdict.personas.map((p: { name: string; tailor: number; ack: number; nolack: number; voice: number; upsell: number; note: string }) =>
        `| ${p.name} | ${p.tailor} | ${p.ack} | ${p.nolack} | ${p.voice} | ${p.upsell || '—'} | ${p.note} |`),
      '',
      `**Overall:** ${verdict.overall}`,
      '',
      `**Top fix:** ${verdict.top_fix}`,
      '',
    ].join('\n')
    fs.appendFileSync(REPORT_PATH, judged)

    // The eval's pass bar is FLEET MEANS, not per-persona minimums — single
    // judge runs swing ±2 on individual personas while the means stay stable.
    // `nolack` excludes transcripts carrying the deliberate honesty beat
    // ("chosen around it"): the judge reads ANY mention of a catalogue gap as
    // apology, but silently substituting dresses for a jeans request is the
    // worse failure — a contested design decision, held on purpose (see wiki:
    // tailor-consultation).
    const honest = new Set(
      visionResults.filter(r => r.turns.some(t => t.assistant.includes('chosen around it')))
        .map(r => r.persona.name),
    )
    type Score = { name: string; tailor: number; ack: number; nolack: number; voice: number; upsell: number }
    const ps: Score[] = verdict.personas
    const mean = (xs: number[]) => xs.reduce((a, b) => a + b, 0) / xs.length
    // Bars calibrated to measured judge variance: with n=8 personas and ±2
    // per-persona noise, observed fleet means straddle 3.75–4.6 on identical
    // engine behavior. 3.5 is the regression floor, not the aspiration.
    expect(mean(ps.map(p => p.tailor))).toBeGreaterThanOrEqual(3.5)
    expect(mean(ps.map(p => p.ack))).toBeGreaterThanOrEqual(4)
    expect(mean(ps.map(p => p.voice))).toBeGreaterThanOrEqual(3.5)
    expect(mean(ps.filter(p => !honest.has(p.name)).map(p => p.nolack))).toBeGreaterThanOrEqual(3.5)
    // Upsell tone over the personas that actually saw add-on groups (0 = none).
    const upsold = ps.filter(p => p.upsell > 0)
    if (upsold.length > 0) {
      expect(mean(upsold.map(p => p.upsell))).toBeGreaterThanOrEqual(3.5)
    }
  }, 120_000)
})
